parameters.jsCode:
const now = new Date();

const ticketId =
  `TKT-${now.getFullYear()}${String(now.getMonth() + 1).padStart(2, '0')}${String(now.getDate()).padStart(2, '0')}-${Math.random().toString(36).substring(2, 7).toUpperCase()}`;

return [{
  json: {
    ...$json,
    ticket_id: ticketId,
    created_at: now.toISOString(),
    status: "Open",
    manager_notified: "No"
  }
}];

